import{_ as p,o as r,c,ah as n,j as a}from"./chunks/framework.eLu1Yovf.js";const d="/projects/uHand_UNO/en/latest/assets/image2.7RINB_oj.webp",h="/projects/uHand_UNO/en/latest/assets/image3.w0AGb8Ve.webp",t="/projects/uHand_UNO/en/latest/assets/image4.BO2IFEhM.webp",g="/projects/uHand_UNO/en/latest/assets/image5.DJXJDDKf.webp",u="/projects/uHand_UNO/en/latest/assets/image6.CwfkAqI0.webp",m="/projects/uHand_UNO/en/latest/assets/image7.CxAOD4Ky.webp",f="/projects/uHand_UNO/en/latest/assets/image8.DBzKzY2N.webp",_="/projects/uHand_UNO/en/latest/assets/image9.x8yLVARu.webp",v="/projects/uHand_UNO/en/latest/assets/image10.DSh7sK6D.webp",b="/projects/uHand_UNO/en/latest/assets/image11.DxvDUtot.webp",y="/projects/uHand_UNO/en/latest/assets/image12.DTnplfBo.webp",w="/projects/uHand_UNO/en/latest/assets/image13.BpBdJRg1.webp",A="/projects/uHand_UNO/en/latest/assets/image14.XtLz_WbY.webp",T="/projects/uHand_UNO/en/latest/assets/image15.jGvzBYMd.webp",x="/projects/uHand_UNO/en/latest/assets/image16.Baze9ucg.webp",C="/projects/uHand_UNO/en/latest/assets/image17.BsKcIfmj.webp",S="/projects/uHand_UNO/en/latest/assets/image18.CQFa79Gs.webp",k="/projects/uHand_UNO/en/latest/assets/image19.gAd-GPR4.webp",P="/projects/uHand_UNO/en/latest/assets/image20.DHYRDDx6.webp",I="/projects/uHand_UNO/en/latest/assets/image21.O-ueJtc7.webp",z="/projects/uHand_UNO/en/latest/assets/image22.CbXPiEZt.webp",U="/projects/uHand_UNO/en/latest/assets/image23.D_T4198d.webp",N="/projects/uHand_UNO/en/latest/assets/image24.BBtn00tz.webp",q="/projects/uHand_UNO/en/latest/assets/image25.CrPv4YdH.webp",B="/projects/uHand_UNO/en/latest/assets/image26.DlG2usEX.webp",D="/projects/uHand_UNO/en/latest/assets/image27.CZE5PA09.webp",O="/projects/uHand_UNO/en/latest/assets/image28.lmhEjQMm.webp",E="/projects/uHand_UNO/en/latest/assets/image29.DOWVM5lZ.webp",R="/projects/uHand_UNO/en/latest/assets/image2.4zZa-Fjt.webp",H="/projects/uHand_UNO/en/latest/assets/image3.ocuAII7N.webp",j="/projects/uHand_UNO/en/latest/assets/image5.DtDmlcoc.webp",M="/projects/uHand_UNO/en/latest/assets/image4.DZRSiHO0.webp",e="/projects/uHand_UNO/en/latest/assets/image7.B5nMPa9p.webp",i="data:image/png;base64,",o="data:image/png;base64,",l="data:image/png;base64,",V="/projects/uHand_UNO/en/latest/assets/image11.BIU0CN7f.webp",Q=JSON.parse('{"title":"9. Wireless Glove Control Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/9.wireless_glove_conntrol_course.md","filePath":"docs/9.wireless_glove_conntrol_course.md"}'),X={name:"docs/9.wireless_glove_conntrol_course.md"};function W(L,s,G,Y,F,Z){return r(),c("div",null,[...s[0]||(s[0]=[n('<h1 id="_9-wireless-glove-control-course" tabindex="-1">9. Wireless Glove Control Course <a class="header-anchor" href="#_9-wireless-glove-control-course" aria-label="Permalink to &quot;9. Wireless Glove Control Course&quot;">​</a></h1><p id="anchor_9_1"></p><h2 id="_9-1-wireless-glove-introduction-and-wearing" tabindex="-1">9.1 Wireless Glove Introduction and Wearing <a class="header-anchor" href="#_9-1-wireless-glove-introduction-and-wearing" aria-label="Permalink to &quot;9.1 Wireless Glove Introduction and Wearing&quot;">​</a></h2><p>The wireless glove consists of five potentiometers and uses a Bluetooth module to communicate with devices.</p><h3 id="_9-1-1-structure-introduction" tabindex="-1">9.1.1 Structure Introduction <a class="header-anchor" href="#_9-1-1-structure-introduction" aria-label="Permalink to &quot;9.1.1 Structure Introduction&quot;">​</a></h3><img loading="lazy" height="671" width="1269" class="common_img" src="'+d+'"><p><strong>Potentiometers</strong>: There are five potentiometers on the back of the wireless glove, which are key components that control the opening and closing of the uHand UNO.</p><p><strong>Gyroscope Acceleration Sensor (MPU6050)</strong>: It can obtain the acceleration and tile angle of the wireless glove in the x,y, and z axes. You can control the uHand UNO by rotating the wireless glove for more operations.</p><p><strong>Bluetooth Module</strong>: It is mainly used for communication between the wireless glove and the uHand UNO.</p><p><strong>Function Keys</strong>: The functions of these two keys are as follows:</p><p><strong>(1) DEL:</strong> Clear the history of Bluetooth connections.</p><p><strong>(2) K3:</strong> Switch the control mode of the wireless glove.</p><p><strong>(3) Reset Key:</strong> Restart the wireless glove.</p><p><strong>(4) LED Indicators:</strong> Display the control mode of the wireless glove.</p><p><strong>(5) USB Port:</strong> Used to connect to a PC for debugging and downloading programs.</p><p><strong>(6) Power Port:</strong> Connect to a lithium battery to power the wireless glove, with a standard voltage of 7.4V.</p><h3 id="_9-1-2-wearing-method" tabindex="-1">9.1.2 Wearing Method <a class="header-anchor" href="#_9-1-2-wearing-method" aria-label="Permalink to &quot;9.1.2 Wearing Method&quot;">​</a></h3><img loading="lazy" height="1055" width="1268" class="common_img" src="'+h+'"><p>Open all straps. First, tie the finger straps at the last knuckles of each finger, and then tie the hand strap and wrist strap at the hand and wrist respectively. The final wearing effect is as follows (please refer to the video in the same path as this document for details):</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="730" width="580" src="'+t+'" style="width:480px;"><img loading="lazy" height="730" width="580" src="'+g+'" style="width:480px;"></p><p>Front Back</p><h3 id="_9-1-3-device-pairing" tabindex="-1">9.1.3 Device Pairing <a class="header-anchor" href="#_9-1-3-device-pairing" aria-label="Permalink to &quot;9.1.3 Device Pairing&quot;">​</a></h3><p>(1) First, switch on the controlled device and ensure it is connected to the Bluetooth module.</p><p>(2) Wear the wireless glove on the right hand, and make a fist with the palm facing down. Then power on the wireless glove and its LED indicators will light up.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="733" width="550" src="'+u+'" style="width:480px;"><img loading="lazy" height="733" width="550" src="'+m+'" style="width:480px;"></p><p>(3) After the LED indicators go off, stretch your hand. When the LEDs complete the second flashing, it means that the initialization of the wireless glove is completed. (This process must be done every time you restart the glove.)</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="733" width="550" src="'+f+'" style="width:480px;"><img loading="lazy" height="733" width="550" src="'+_+'" style="width:480px;"></p><p>(4) Press the <strong>&#39;DEL&#39;</strong> key to clear the history of the Bluetooth connections.</p><p>(5) After the clear is completed, the <strong>&#39;STA&#39;</strong> indicator starts to flash, and the wireless glove will automatically connect to the device. When the connection is successful, the &quot;<strong>STA</strong>&quot; indicator stays on.</p><img loading="lazy" height="733" width="550" class="common_img" src="'+v+'"><h3 id="_9-1-4-control-modes-switching" tabindex="-1">9.1.4 Control Modes Switching <a class="header-anchor" href="#_9-1-4-control-modes-switching" aria-label="Permalink to &quot;9.1.4 Control Modes Switching&quot;">​</a></h3><p>You can press the <strong>&#39;K3&#39;</strong> key on the wireless glove to switch control modes. The LEDs (D1 to D5) will provide feedback on the currently selected mode.</p><img loading="lazy" height="370" width="659" class="common_img" src="'+b+'"><p>The corresponding relationship between the LED status and the mode is shown in the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">LED status(D1-D5)</th><th style="text-align:center;">Mode</th></tr></thead><tbody><tr><td style="text-align:center;">All off</td><td style="text-align:center;">Biorobot Control Mode</td></tr><tr><td style="text-align:center;">1 on (D1)</td><td style="text-align:center;">Robotic Hand Control Mode (Right Hand)</td></tr><tr><td style="text-align:center;">2 on (D1, D2)</td><td style="text-align:center;">Tank Control Mode</td></tr><tr><td style="text-align:center;">3 on (D1, D2, D3)</td><td style="text-align:center;">Robotic Arm Control Mode (PWM Servo Drive)</td></tr><tr><td style="text-align:center;">4 on (D1, D2, D3, D4)</td><td style="text-align:center;">Robotic Hand Control Mode (Left Hand)</td></tr><tr><td style="text-align:center;">5 on (D1, D2, D3, D4, D5)</td><td style="text-align:center;">Robotic Arm Control Mode (Bus Servo Drive)</td></tr></tbody></table><h3 id="_9-1-5-control-mode-instruction" tabindex="-1">9.1.5 Control Mode Instruction <a class="header-anchor" href="#_9-1-5-control-mode-instruction" aria-label="Permalink to &quot;9.1.5 Control Mode Instruction&quot;">​</a></h3><p>The wireless glove has four control modes, which are used for controlling products in the biorobot series, robotic hand series, tank robot series, and robotic arm series with a built-in Bluetooth module. The specific control methods for each type of product are shown in the table below:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Product Type</th><th style="text-align:center;">Examples</th></tr></thead><tbody><tr><td style="text-align:center;">Biorobot Series</td><td style="text-align:center;">Narrow-footed robot, Cross-footed robot, Spiderbot</td></tr><tr><td style="text-align:center;">Tank Robot Series</td><td style="text-align:center;">Tankbot</td></tr><tr><td style="text-align:center;">Robotic Hand Series</td><td style="text-align:center;">uHand, uHand UNO</td></tr><tr><td style="text-align:center;">Robotic Arm Series</td><td style="text-align:center;">LeArm, xArm 1S, MiniArm</td></tr></tbody></table><ul><li><strong>Biorobot</strong></li></ul><p>The control of biorobot is mainly achieved through gesture control to make the robot perform a set of action groups:</p><div class="wy-table-responsive"><table border="1" class="docutils-nobg"><thead><tr><th style="text-align:center;">Gesture Description</th><th style="text-align:center;width:180px;">Gesture Image</th><th style="text-align:center;">Biorobot Feedback Action(from the robot&#39;s view)</th></tr></thead><tbody><tr><td style="text-align:center;">Extend your middle finger, crook your ring finger, and tilt the palm to the right.</td><td style="text-align:center;"><img loading="lazy" height="314" width="236" src="'+y+'"></td><td style="text-align:center;">Turn right</td></tr><tr><td style="text-align:center;">Extend your middle finger, crook your ring finger, and tilt the palm to the left.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+w+'"></td><td style="text-align:center;">Turn left</td></tr><tr><td style="text-align:center;">Make a fist with the palm facing down.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+A+'"></td><td style="text-align:center;">Stop</td></tr><tr><td style="text-align:center;">Stretch your hand (straighten your middle finger) with the palm facing down.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+T+'"></td><td style="text-align:center;">Move forward</td></tr><tr><td style="text-align:center;">Crook your middle finger, and straighten your little finger with the palm facing up (Spider-Man gesture).</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+x+'"></td><td style="text-align:center;">Move backward</td></tr><tr><td style="text-align:center;">Stretch your hand with the palm facing up.</td><td style="text-align:center;"><img loading="lazy" height="308" width="231" src="'+C+'"></td><td style="text-align:center;">Stop</td></tr></tbody></table></div><ul><li><strong>Tank Robot</strong></li></ul><p>You can control the tank robot by making specific gestures. The following table shows the available gestures and their corresponding feedback actions from the tank:</p><div class="wy-table-responsive"><table class="docutils-nobg" style="text-align:center;" border="1"><thead><tr><th>Initial Gesture</th><th>Gesture Description (from your perspective)</th><th style="width:180px;">Gesture Image</th><th>Feedback Action from the Tank Robot (from the tank robot&#39;s perspective)</th></tr></thead><tbody><tr><td rowspan="4">Straighten your index and middle fingers, with the palm facing down (other fingers crooked in).</td><td>Raise your wrist, that is, your straightened fingers point forward and upward.</td><td><img loading="lazy" height="308" width="231" src="'+S+'"></td><td>Move forward</td></tr><tr><td>Bend your wrist downward, that is, your straightened fingers point forward and downward.</td><td><img loading="lazy" height="308" width="231" src="'+k+'"></td><td>Move backward</td></tr><tr><td>Bend your wrist clockwise, that is, the palm faces to the left.</td><td><img loading="lazy" height="308" width="231" src="'+P+'"></td><td>Rotate clockwise in place.</td></tr><tr><td>Bend your wrist counterclockwise, that is, the palm faces to the right.</td><td><img loading="lazy" height="308" width="231" src="'+I+'"></td><td>Rotate counterclockwise in place.</td></tr><tr><td colspan="3">Other Gestures</td><td>Stop</td></tr></tbody></table></div><ul><li><strong>Robotic Hand</strong></li></ul><p>By bending or straightening your fingers, you can control the bending or straightening of the robotic hands&#39; corresponding fingers:</p><div class="wy-table-responsive"><table class="docutils-nobg" style="text-align:center;" border="1"><thead><tr><th>Potentiometer Position</th><th style="width:180px;">Gesture Image</th><th>Servo Controlled</th></tr></thead><tbody><tr><td colspan="2">Thumb</td><td>Servo 1</td></tr><tr><td colspan="2">Index Finger</td><td>Servo 2</td></tr><tr><td colspan="2">Middle Finger</td><td>Servo 3</td></tr><tr><td colspan="2">Ring Finger</td><td>Servo 4</td></tr><tr><td colspan="2">Little Finger</td><td>Servo 5</td></tr><tr><td>Stretch your hand with the palm facing down, and your wrist rotates clockwise.</td><td><img loading="lazy" height="308" width="231" src="'+z+'"></td><td>The Pan-tilt rotates counterclockwise (from the perspective of the robotic hand).</td></tr><tr><td>Stretch your hand with the palm facing down, and the wrist rotates counterclockwise.</td><td><img loading="lazy" height="308" width="231" src="'+U+'"></td><td>The Pan-tilt rotates clockwise (from the perspective of the robotic hand).</td></tr></tbody></table></div><ul><li><strong>Robotic Arm</strong></li></ul><p>You can control the robotic arm servos by making specific gestures. The following table shows the available gestures and the corresponding servo numbers they control:</p><div class="wy-table-responsive"><table class="docutils-nobg" style="text-align:center;" border="1"><thead><tr><th>Initial Gesture</th><th>Gesture Description</th><th style="width:180px;">Gesture Image</th><th>Servo Controlled</th></tr></thead><tbody><tr><td rowspan="5">The palm faces down.</td><td>Extend your index finger and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+N+'"></td><td>Servo 1</td></tr><tr><td>Extend your index and middle fingers, and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+q+'"></td><td>Servo 2</td></tr><tr><td>Extend your middle, ring, and little fingers, and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+B+'"></td><td>Servo 3</td></tr><tr><td>Extend your four fingers, and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+D+'"></td><td>Servo 4</td></tr><tr><td>Stretch your hand with the palm facing down, and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+O+'"></td><td>Servo 5</td></tr><tr><td>The palm faces down.</td><td>Make a fist with the palm facing down, and tilt to the left or right.</td><td><img loading="lazy" height="308" width="231" src="'+E+'"></td><td>Servo 6</td></tr></tbody></table></div><h2 id="_9-2-wireless-glove-control" tabindex="-1">9.2 Wireless Glove Control <a class="header-anchor" href="#_9-2-wireless-glove-control" aria-label="Permalink to &quot;9.2 Wireless Glove Control&quot;">​</a></h2><p>In this section, you can learn how to control the robot hand through five potentiometers of the wireless glove.</p><h3 id="_9-2-1-getting-ready" tabindex="-1">9.2.1 Getting Ready <a class="header-anchor" href="#_9-2-1-getting-ready" aria-label="Permalink to &quot;9.2.1 Getting Ready&quot;">​</a></h3><p>(1) Connect the Bluetooth module to the robotic hand.</p><img loading="lazy" height="915" width="1267" class="common_img" src="'+R+'"><p>(2) Put the wireless glove on according to the &quot;<a href="#anchor_9_1"><strong>9.1 Wireless Glove Introduction and Wearing</strong></a>&quot;.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="578" width="459" src="'+H+'" style="width:480px;"><img loading="lazy" height="730" width="580" src="'+t+'" style="width:480px;"></p><p>(3) According to the <a href="#anchor_9_1">&quot;<strong>9.1 Wireless Glove Introduction and Connection</strong>&quot;</a>, connect the wireless glove to the robotic hand.</p><h3 id="_9-2-2-program-download" tabindex="-1">9.2.2 Program Download <a class="header-anchor" href="#_9-2-2-program-download" aria-label="Permalink to &quot;9.2.2 Program Download&quot;">​</a></h3><ul><li><strong>uHand Client Program Download</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The Bluetooth must be removed before downloading the program, otherwise the download will fail due to the serial port conflict.</p></div><p>(1) Locate and find the uHand client program in the same directory as this section, and open the <a href="../_static/source_code/blue_uhand.zip">blue_uhand.ino</a> program file.</p><img loading="lazy" height="147" width="652" class="common_img" src="'+j+'"><p>(2) Connect the Arduino to the computer through a UNO cable (Type-B).</p><img loading="lazy" height="725" width="1039" class="common_img" src="'+M+'"><p>(3) Click the <strong>&quot;Select Board&quot;</strong>, the software will automatically detect the current Arduino serial interface, then click to connect.</p><img loading="lazy" height="141" width="655" class="common_img" src="'+e+'" style="width:650px;"><p>(4) Click <img loading="lazy" height="49" width="48" src="'+i+'"> to download the program to Arduino, and then wait for the download to complete.</p><img loading="lazy" height="39" width="655" class="common_img" src="'+o+'" style="width:650px;"><img loading="lazy" height="41" width="499" class="common_img" src="'+l+'" style="width:650px;"><ul><li><strong>Wireless Glove Program Download</strong></li></ul><p>The program is preloaded onto the wireless glove at the factory, so this section is for information purposes only.</p><p>(1) Locate and open the <a href="../_static/source_code/lehand.zip">lehand.ino</a> program file in the same directory as this section.</p><img loading="lazy" height="228" width="752" class="common_img" src="'+V+'"><p>(2) Connect the wireless glove to the computer through micro USB cable.</p><p>(3) Click the <strong>&quot;Select Board&quot;</strong>, the software will automatically detect the current Arduino port. Then click to connect.</p><img loading="lazy" height="141" width="655" class="common_img" src="'+e+'" style="width:650px;"><p>(4) Click <img loading="lazy" height="49" width="48" src="'+i+'"> to download the program to Arduino, and then wait for the download to complete.</p><img loading="lazy" height="39" width="655" class="common_img" src="'+o+'" style="width:650px;"><img loading="lazy" height="41" width="499" class="common_img" src="'+l+'" style="width:650px;"><h3 id="_9-2-3-program-outcome" tabindex="-1">9.2.3 Program Outcome <a class="header-anchor" href="#_9-2-3-program-outcome" aria-label="Permalink to &quot;9.2.3 Program Outcome&quot;">​</a></h3><p>After connecting the wireless glove to the robot hand, the rotation of the robot hand servo can be controlled through the potentiometer of glove, and the pan-tilt servo rotation can be controlled through robot wrist. Specific information can be found in the following table.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Potentiometer Position</th><th style="text-align:center;">Servo Control</th></tr></thead><tbody><tr><td style="text-align:center;">Thumb</td><td style="text-align:center;">Servo No.1</td></tr><tr><td style="text-align:center;">Index finger</td><td style="text-align:center;">Servo No.2</td></tr><tr><td style="text-align:center;">Middle finger</td><td style="text-align:center;">Servo No.3</td></tr><tr><td style="text-align:center;">Ring finger</td><td style="text-align:center;">Servo No.4</td></tr><tr><td style="text-align:center;">Pinkie</td><td style="text-align:center;">Servo No.5</td></tr><tr><td style="text-align:center;">Rotate your wrists clockwise with the palm facing down</td><td style="text-align:center;">Pan-tilt servo rotates anticlockwise. Take hand as the first view.</td></tr><tr><td style="text-align:center;">Rotate your wrists counterclockwise with the palm facing down</td><td style="text-align:center;">Pan-tilt servo rotates clockwise. Take hand as the first view.</td></tr></tbody></table><h3 id="_9-2-4-brief-program-analysis" tabindex="-1">9.2.4 Brief Program Analysis <a class="header-anchor" href="#_9-2-4-brief-program-analysis" aria-label="Permalink to &quot;9.2.4 Brief Program Analysis&quot;">​</a></h3><p><a href="../_static/source_code/lehand.zip">uHand UNO Program</a></p><p>Below is the analysis of the program of the robotic hand <a href="../_static/source_code/blue_uhand.zip">blue_uhand.ino</a>, and wireless glove <a href="../_static/source_code/lehand.zip">lehand.ino</a>.</p><ul><li><strong>Robot Hand Program Analysis</strong></li></ul><p>(1) Import Library File</p><p>Import the RGB control library, servo control library, Bluetooth reception and other library files required for this program.</p>',89),a("p",{"lineno-start":"1"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;FastLED.h&gt;</span><span> //RGB控制库（需要导入库）(RGB control library(need to import libraries))</span></span>
<span class="line"><span>#include &lt;Servo.h&gt;</span><span> //舵机库(servo library)</span></span>
<span class="line"><span>#include &quot;tone.h&quot;</span><span> //音调库(tone library)</span></span>
<span class="line"><span>#include &quot;bluetooth.h&quot;</span><span> //蓝牙接收库(Bluetooth receiving library)</span></span></code></pre></div><p>(2) Define Pins and Create Objects</p><p>Firstly, define Arduino pins used for connecting hardware, mainly consisting of six servo pins, one buzzer pin and one RGB light pin.</p>`,3),a("p",{"lineno-start":"13"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//按键引脚(button pin)</span></span>
<span class="line"><span>const static uint8_t keyPins[2] = { 8, 9 };</span></span>
<span class="line"><span>// 舵机引脚(servo pin)</span></span>
<span class="line"><span>const static uint8_t servoPins[6] = { 7, 6, 5, 4, 3, 2 };</span></span>
<span class="line"><span>// 蜂鸣器引脚(buzzer pin)</span></span>
<span class="line"><span>const static uint8_t buzzerPin = 11;</span></span>
<span class="line"><span>// RGB灯引脚(RGB LED pin)</span></span>
<span class="line"><span>const static uint8_t rgbPin = 13;</span></span></code></pre></div><p>Next, define the variables used for controlling RGB light and servo. The &quot;<strong>extended_func_angles</strong>&quot; array is used for storing desired angle of each servo. The &quot;<strong>servo_angles</strong>&quot; array is used for storing actual angle of servo.</p>`,2),a("p",{"lineno-start":"22"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// RGB灯颜色对象(RGB LED color object)</span></span>
<span class="line"><span>static CRGB rgbs[1];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 舵机角度相关变量 （舵机下标对应的位置： 0-大拇指 1-食指 2-中指 3-无名指 4-小指 5-云台）(variables related to servo angles (the corresponding relationship between the servos and the robotic hand: 0-thumb, 1-index finger, 2-middle finger, 3-ring finger, 4-pinky finger, and 5-pan-tilt))</span></span>
<span class="line"><span>static uint8_t extended_func_angles[6] = { 90, 90, 90, 90, 90, 90 }; /* 二次开发例程使用的角度数值(angle values used for secondary development) */</span></span>
<span class="line"><span>static uint8_t servo_angles[6] = { 90, 90, 90, 90, 90, 90 };  /* 舵机实际控制的角度数值(angle values for actual servo control) */</span></span></code></pre></div><p>As the desired value may differ from the actual value during servo rotation control, the control functions should execute the following line of code: <code>servo_angles[i] = servo_angles[i] * 0.85 + extended_func_angles[i] * 0.15</code>. This will allow the servo to gradually approach the target position.</p><p>The calling will add the pulse width by a fraction of the desired value to the current position prior to servo movement. Once the motion concludes, the current data will be updated with a new value. This mechanism facilitates the stop of the robot hand upon reaching the target position.</p>`,3),a("p",{"lineno-start":"130"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 舵机控制任务(servo control task)</span></span>
<span class="line"><span>void servo_control(void) {</span></span>
<span class="line"><span>  static uint32_t last_tick = 0;</span></span>
<span class="line"><span>  // 间隔25毫秒(interval 25 microseconds)</span></span>
<span class="line"><span>  if (millis() - last_tick &lt; 25) {</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  last_tick = millis();</span></span>
<span class="line"><span>  // 对6个舵机分别赋值(assign values to the six servos individually)</span></span>
<span class="line"><span>  for (int i = 0; i &lt; 6; ++i) {</span></span>
<span class="line"><span>    servo_angles[i] = servo_angles[i] * 0.85 + extended_func_angles[i] * 0.15;</span></span>
<span class="line"><span>    servos[i].write(i == 0 || i == 5 ? 180 - servo_angles[i] : servo_angles[i]);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Create servo control objects, Bluetooth receiving objects and Bluetooth receiving storage variables for proceeding control and reading data. Declare task function to perform different control tasks. The <code>servo_control</code> function is used for controlling servo; <code>tune_task</code> is used for controlling buzzer; <code>blue_task</code> is used for controlling the Bluetooth module.</p>`,2),a("p",{"lineno-start":"34"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 创建舵机控制对象(create servo control object)</span></span>
<span class="line"><span>Servo servos[6];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 创建蓝牙接收对象(create Bluetooth receiving object)</span></span>
<span class="line"><span>blue_controller blue_ctl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 创建蓝牙接收存储变量(create Bluetooth receiving storage variable)</span></span>
<span class="line"><span>struct uHand_Servo uhand_servos;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 舵机控制任务(servo contorl task)</span></span>
<span class="line"><span>static void servo_control(void);</span></span>
<span class="line"><span>// 蜂鸣器鸣响函数(buzzer sound function)</span></span>
<span class="line"><span>void play_tune(uint16_t *p, uint32_t beat, uint16_t len);</span></span>
<span class="line"><span>// 蜂鸣器任务(buzzer task)</span></span>
<span class="line"><span>void tune_task(void);</span></span>
<span class="line"><span>// 蓝牙控制任务(Bluetooth control task)</span></span>
<span class="line"><span>void blue_task(void);</span></span></code></pre></div><p>(3) Initial Settings</p><p>Set up the necessary hardware equipment in the <code>setup()</code> function. Firstly, initialize the serial interface, configuring the baud rate for communication to 9600 and setting the timeout for date reading to 500ms.</p>`,3),a("p",{"lineno-start":"53"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 初始化串口并设置速率(initialize serial port and set velocity)</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  // 设置串行端口读取数据的超时时间(set timeout for serial port reading data)</span></span>
<span class="line"><span>  Serial.setTimeout(500);</span></span></code></pre></div><p>Set the pin of buzzer to output mode.</p>`,2),a("p",{"lineno-start":"60"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 初始化蜂鸣器引脚(initialize buzzer pin)</span></span>
<span class="line"><span>  pinMode(buzzerPin, OUTPUT);</span></span></code></pre></div><p>Assign the servo IO port to facilitate the control through pin.</p>`,2),a("p",{"lineno-start":"62"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 绑定舵机IO口(bind servo IO port)</span></span>
<span class="line"><span>  for (int i = 0; i &lt; 6; ++i) {</span></span>
<span class="line"><span>    servos[i].attach(servoPins[i]);</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>Use the <code>FastLED</code> library to initialize the RGB light on the expansion board, and connect it to the RGB pin. Then set the color to green through <code>rgbs[0] = CRGB(0, 255, 0)</code>, and use the <code>FastLED.show</code> function to illuminate the set color at last.</p>`,2),a("p",{"lineno-start":"66"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 初始化RGB控制对象(initialize RGB control object)</span></span>
<span class="line"><span>  FastLED.addLeds&lt;WS2812, rgbPin, GRB&gt;(rgbs, 1);</span></span>
<span class="line"><span>  // 初始化颜色对象(initialize color object)</span></span>
<span class="line"><span>  rgbs[0] = CRGB(0, 255, 0);</span></span>
<span class="line"><span>  // 根据颜色发光(light up based on the color)</span></span>
<span class="line"><span>  FastLED.show();</span></span></code></pre></div><p>Use the <code>tone</code> and <code>noTone</code> functions to set the buzzer to emit a short sound at a frequency of 1000Hz before turning off.</p>`,2),a("p",{"lineno-start":"73"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> tone(buzzerPin, 1000);</span></span>
<span class="line"><span>  // 延时(delay)</span></span>
<span class="line"><span>  delay(100);</span></span>
<span class="line"><span>  // 蜂鸣器停止(the buzzer stops)</span></span>
<span class="line"><span>  noTone(buzzerPin); //将TOUCH配置为输入(输入状态一般是将要读取这个引脚的状态，即读取传感器的反馈值）(configure the TOUCH pin as an input (input state is typically used to read the status of this pin, i.e., to read the feedback value from the sensor))</span></span></code></pre></div><p>(4) Bluetooth Control</p><p>The Bluetooth task function <code>blue_task</code> is mainly used for receiving Bluetooth signal and controlling the rotation of robot hand servo.</p><p>Firstly the program obtains the information of the servo position through Bluetooth controller <code>blue_ctl</code>, and stores it in the <code>uhand_servos</code>.</p>`,4),a("p",{"lineno-start":"93"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 蓝牙控制任务(Bluetooth control task)</span></span>
<span class="line"><span>void blue_task(void)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  // 获取蓝牙信息(obtain Bluetooth information)</span></span>
<span class="line"><span>  bool rt = blue_ctl.get_servos(&amp;uhand_servos);</span></span>
<span class="line"><span>  // 若成功(if it is successful)</span></span></code></pre></div><p>If the information is obtained successfully, the variable &quot;<strong>rt</strong>&quot; is set to &quot;<strong>True</strong>&quot;, and the program proceeds to the next step. Utilize a &quot;<strong>for</strong>&quot; loop to iterate over all servo information, with different controls executed based on the mapping of the five potentiometers on the glove to their corresponding servo ID numbers.</p><p>Case 1 corresponds to the thumb. The servo&#39;s rotation angle is inversly proportional to the potentiometer&#39;s rotation value. That is to say, when receive the potentiometer position within the range of 1100~1950, the actual rotation angle mapped to the servo is 180~0.</p><p>Case 2, case 3, case 4, case 5 corresponds to index finger, middle finger, ring finger and pinkie respectively. These servo rotation angles are also opposite to the corresponding potentiometer value of glove.</p><p>Case 6 corresponds to pan-tilt rotation. The threshold range of this portion is 600-2400, and the corresponding rotation angle is 0-180.</p>`,5),a("p",{"lineno-start":"98"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 若成功(if it is successful)</span></span>
<span class="line"><span>  if(rt)</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    // 将接收到的舵机位置赋值给uHand的对应舵机(assign the received servo position to the corresponding servo of uHand UNO)</span></span>
<span class="line"><span>    for(int i = 0; i &lt; uhand_servos.num ; i++)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      // 根据ID号赋值(assign values based on the ID number)</span></span>
<span class="line"><span>      // 注意：ID号是从1开始的，而舵机角度数组下标是从0开始的，赋值需要（ID-1）(Note: The ID number starts from 1, and the servo angle array index starts from 0. Therefore, assigning values requires subtracting 1 from the ID)</span></span>
<span class="line"><span>      switch(uhand_servos.servos[i].ID)</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        case 1: //大拇指，转动角度为相反的(thumb; rotate in the opposite direction)</span></span>
<span class="line"><span>          extended_func_angles[uhand_servos.servos[i].ID - 1] = map(uhand_servos.servos[i].Position , 1100 , 1950 , 180 , 0);</span></span>
<span class="line"><span>          break;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        case 2: //食指 ~ 小拇指(index finger - little finger)</span></span>
<span class="line"><span>        case 3:</span></span>
<span class="line"><span>        case 4:</span></span>
<span class="line"><span>        case 5:</span></span>
<span class="line"><span>          // 将对应的阈值范围映射到[0,180]的范围内，赋值给舵机(Map the corresponding threshold range to the range of 0 to 180, and assign it to the servo)</span></span>
<span class="line"><span>          extended_func_angles[uhand_servos.servos[i].ID - 1] = map(uhand_servos.servos[i].Position , 1100 , 1950 , 0, 180);</span></span>
<span class="line"><span>          break;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        case 6: //云台转动(pan-tilt rotates)</span></span>
<span class="line"><span>          // 将对应的阈值范围映射到[0,180]的范围内，赋值给舵机(Map the corresponding threshold range to the range of 0 to 180, and assign it to the servo)</span></span>
<span class="line"><span>          extended_func_angles[uhand_servos.servos[i].ID - 1] = map(uhand_servos.servos[i].Position , 600 , 2400 , 0, 180);</span></span>
<span class="line"><span>          break;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span></code></pre></div><ul><li><strong>Wireless Glove Program Analysis</strong></li></ul><p><a href="../_static/source_code/blue_uhand.zip">Wireless Glove Program</a></p><p>(1) Import Library File</p><p>Import the soft serial library, robot controlling signal library, MPU6050 library and I2C library file required for this program.</p>`,5),a("p",{"lineno-start":"1"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;SoftwareSerial.h&gt;</span><span> //软串口库(Software serial library)</span></span>
<span class="line"><span>#include &quot;LobotServoController.h&quot;</span><span> //机器人控制信号库(Robot control signal library)</span></span>
<span class="line"><span>#include &quot;MPU6050.h&quot;</span><span> //MPU6050库(MPU6050 library)</span></span>
<span class="line"><span>#include &quot;Wire.h&quot;</span><span> //IIC库(I2C library)</span></span></code></pre></div><p>(2) Define Pins and Create Objects</p><p>Firstly, set the Bluetooth module RX, TX of wireless glove to 11 and 12. Then limit the range of potentiometer to 0~255, and set the servo position of robot hand to 1500 to facilitate the proceeding map.</p><p>Set the calibration flag to &quot;<strong>True</strong>&quot;, initialize the Bluetooth communication port and create control object of the robot.</p>`,4),a("p",{"lineno-start":"6"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 蓝牙TX、RX引脚(Bluetooth TX and RX pins)</span></span>
<span class="line"><span>#define BTH_RX 11</span></span>
<span class="line"><span>#define BTH_TX 12</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 创建变位器最小值和最大值存储(Create minimum and maximum values for the potentiometers)</span></span>
<span class="line"><span>float min_list[5] = {0, 0, 0, 0, 0};</span></span>
<span class="line"><span>float max_list[5] = {255, 255, 255, 255, 255};</span></span>
<span class="line"><span>// 各个手指读取到的数据变量(Data variables read by each finger)</span></span>
<span class="line"><span>float sampling[5] = {0, 0, 0, 0, 0}; </span></span>
<span class="line"><span>// 手指相关舵机变量(Variables for controlling the servos of each finger)</span></span>
<span class="line"><span>float data[5] = {1500, 1500, 1500, 1500, 1500};</span></span>
<span class="line"><span>uint16_t ServePwm[5] = {1500, 1500, 1500, 1500, 1500};</span></span>
<span class="line"><span>uint16_t ServoPwmSet[5] = {1500, 1500, 1500, 1500, 1500};</span></span>
<span class="line"><span>// 电位器校准标志位(Flag for potentiometer calibration)</span></span>
<span class="line"><span>bool turn_on = true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 蓝牙通讯串口初始化(Bluetooth communication serial port initialization)</span></span>
<span class="line"><span>SoftwareSerial Bth(BTH_RX, BTH_TX);</span></span>
<span class="line"><span>// 机器人控制对象(Robot control object)</span></span>
<span class="line"><span>LobotServoController lsc(Bth);</span></span></code></pre></div><p>Next, define mapping function. The mapping function receives five floating-point parameters: &quot;<strong>in</strong>&quot;, &quot;<strong>left_in</strong>&quot;, &quot;<strong>right_in</strong>&quot;, &quot;<strong>left_out</strong>&quot;, and &quot;<strong>right_out</strong>&quot;. This function maps the input values from the range &quot;<strong>in</strong>&quot; to &quot;<strong>left_in</strong>&quot; to &quot;<strong>right_in</strong>&quot; to the range &quot;<strong>left_out</strong>&quot; to &quot;<strong>right_out</strong>&quot;, and returns the mapped values.</p>`,2),a("p",{"lineno-start":"27"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 浮点数映射函数(Float mapping function)</span></span>
<span class="line"><span>float float_map(float in, float left_in, float right_in, float left_out, float right_out)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  return (in - left_in) * (right_out - left_out) / (right_in - left_in) + left_out;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Declare variables related to the MPU6050 gyroscope. For example, the ax, ay, az are used for storing raw data of accelerometer. The MPU6050, a commonly used six-axis motion tracking sensor, consists of three-axis gyroscope and three-axis accelerometer.</p><p>The gx, gy, gz are used for storing the raw data of gyroscope; ax0, ay0, az0 are calibrated values of the accelerometer data; gx0, gy0, gz0 are calibrated value of the gyroscope data, etc.</p><p>In addition, there are some variables related to acceleration calibration, which are used for calibrating sensor data. After reading raw data, subtract offset from these raw data in order to obtain a more accurate result.</p>`,4),a("p",{"lineno-start":"33"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// MPU6050相关变量(MPU6050 related variables)</span></span>
<span class="line"><span>MPU6050 accelgyro;</span></span>
<span class="line"><span>int16_t ax, ay, az;</span></span>
<span class="line"><span>int16_t gx, gy, gz;</span></span>
<span class="line"><span>float ax0, ay0, az0;</span></span>
<span class="line"><span>float gx0, gy0, gz0;</span></span>
<span class="line"><span>float ax1, ay1, az1;</span></span>
<span class="line"><span>float gx1, gy1, gz1;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 加速度校准变量(Acceleration calibration variables)</span></span>
<span class="line"><span>int ax_offset, ay_offset, az_offset, gx_offset, gy_offset, gz_offset;</span></span></code></pre></div><p>(3) Initial Settings</p><p>First, the program will set the baud rate of the serial interface to 9600; set the function key K3 and five potentiometers of wireless glove to output mode; and set the D1~D5 LED light of wireless glove to output mode.</p>`,3),a("p",{"lineno-start":"46"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void setup() {</span></span>
<span class="line"><span>  // put your setup code here, to run once:</span></span>
<span class="line"><span>  Serial.begin(9600);</span></span>
<span class="line"><span>  //功能按键初始化(Function key initialization)</span></span>
<span class="line"><span>  pinMode(7, INPUT_PULLUP);</span></span>
<span class="line"><span>  //各手指电位器配置(Configuration of potentiometers for each finger)</span></span>
<span class="line"><span>  pinMode(A0, INPUT);</span></span>
<span class="line"><span>  pinMode(A1, INPUT);</span></span>
<span class="line"><span>  pinMode(A2, INPUT);</span></span>
<span class="line"><span>  pinMode(A3, INPUT);</span></span>
<span class="line"><span>  pinMode(A6, INPUT);</span></span>
<span class="line"><span>  //LED 灯配置(LED light configuration)</span></span>
<span class="line"><span>  pinMode(2, OUTPUT);</span></span>
<span class="line"><span>  pinMode(3, OUTPUT);</span></span>
<span class="line"><span>  pinMode(4, OUTPUT);</span></span>
<span class="line"><span>  pinMode(5, OUTPUT);</span></span>
<span class="line"><span>  pinMode(6, OUTPUT);</span></span></code></pre></div><p>Next, to make sure the Bluetooth module activate in correct mode, initialize the Bluetooth port communication and set the baud rate to 9600. Then send two AT orders to the Bluetooth module: one is to set the Bluetooth to main mode, another one is to soft reboot the Bluetooth module.</p><p>The I2C communication is initialized at first and then the I2C clock frequency is set in the MPU6050 configuration. After the MPU6050 sensor is initialized, the range of the angular velocity and acceleration are set and the current angular velocity and acceleration data are read for subsequent calibration. At last, the read data store in corresponding offset variables, which could used for calibrating subsequent read date.</p>`,3),a("p",{"lineno-start":"64"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  //蓝牙配置(Bluetooth configuration)</span></span>
<span class="line"><span>  Bth.begin(9600);</span></span>
<span class="line"><span>  Bth.print(&quot;AT+ROLE=M&quot;);  //蓝牙配置为主模式(Configure Bluetooth as main mode)</span></span>
<span class="line"><span>  delay(100);</span></span>
<span class="line"><span>  Bth.print(&quot;AT+RESET&quot;);  //软重启蓝牙模块(Soft reset the Bluetooth module)</span></span>
<span class="line"><span>  delay(250);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  //MPU6050 配置(MPU6050 configuration)</span></span>
<span class="line"><span>  Wire.begin();</span></span>
<span class="line"><span>  Wire.setClock(20000);</span></span>
<span class="line"><span>  accelgyro.initialize();</span></span>
<span class="line"><span>  accelgyro.setFullScaleGyroRange(3); //设定角速度量程(Set the angular velocity range)</span></span>
<span class="line"><span>  accelgyro.setFullScaleAccelRange(1); //设定加速度量程(Set the acceletation range)</span></span>
<span class="line"><span>  delay(200);</span></span>
<span class="line"><span>  accelgyro.getMotion6(&amp;ax, &amp;ay, &amp;az, &amp;gx, &amp;gy, &amp;gz);  //获取当前各轴数据以校准(Get current axis data for calibration)</span></span>
<span class="line"><span>  ax_offset = ax;  //X轴加速度校准数据(X-axis acceleration calibration data)</span></span>
<span class="line"><span>  ay_offset = ay;  //Y轴加速度校准数据(Y-axis acceleration calibration data)</span></span>
<span class="line"><span>  az_offset = az - 8192;  //Z轴加速度校准数据(Z-axis acceleration calibration data)</span></span>
<span class="line"><span>  gx_offset = gx; //X轴角速度校准数据(X-axis angular velocity calibration data)</span></span>
<span class="line"><span>  gy_offset = gy; //Y轴角速度校准数据(Y-axis angular velocity calibration data)</span></span>
<span class="line"><span>  gz_offset = gz; //Z轴角速度校准数据(Z-axis angular velocity calibration data)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>(4) Getting Data</p><p>This content is about getting the data of fingers bending angle. The data is obtained through the <code>finger</code> function defined in the main function.</p><p>First, define the <code>timer_sampling</code> and <code>timer_init</code> two static variables. There values are held constant between function calls. The &quot;<strong>init_step</strong>&quot; variable is used for tracking initialization. The <code>sampling[]&quot; and &quot;data[]</code> are used for storing read array of sensor data. <code>min_llist[]</code> and <code>max_list[]</code> are used for storing array of minimum and maximum detected values.</p><p>Loop through the &quot;<strong>for</strong>&quot; function to get the finger sensor data. For each finger, in order to minimize the effect of occasional reading errors or outliers, reads simulated value by code and divides it by 2 after adding it to a cumulative value to get obtain a average value.</p><p>Then use the <code>float_map</code> function to map the average value to a range of 500-2500 pulse-widths for the corresponding servo of robot hand.</p>`,6),a("p",{"lineno-start":"88"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void finger() {</span></span>
<span class="line"><span>  static uint32_t timer_sampling;</span></span>
<span class="line"><span>  static uint32_t timer_init;</span></span>
<span class="line"><span>  static uint8_t init_step = 0;</span></span>
<span class="line"><span>  if (timer_sampling &lt;= millis())</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    for (int i = 14; i &lt;= 18; i++)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      if (i &lt; 18)</span></span>
<span class="line"><span>        sampling[i - 14] += analogRead(i); //读取各个手指的数据(Read data from each finger)</span></span>
<span class="line"><span>      else</span></span>
<span class="line"><span>        sampling[i - 14] += analogRead(A6);  //读取小拇指的数据， 因为IIC 用了 A4,A5 口，所以不能从A0 开始连续读取(Read data from the little finger, because I2C uses A4 and A5 pins. It cannot read continuously from A0)</span></span>
<span class="line"><span>      sampling[i - 14] = sampling[i - 14] / 2.0; //取上次和本次测量值的均值(Take the average of the previous and current measurements)</span></span>
<span class="line"><span>      data[i - 14 ] = float_map( sampling[i - 14],min_list[i - 14], max_list[i - 14], 2500, 500); //将测量值映射到500-2500， 握紧手时为500， 张开时为2500(Map the measurement value to 500 to 2500, with 500 for gripping and 2500 for opening)</span></span>
<span class="line"><span>      data[i - 14] = data[i - 14] &gt; 2500 ? 2500 : data[i - 14];  // 限制最大值为2500(Limit the maximum value to 2500)</span></span>
<span class="line"><span>      data[i - 14] = data[i - 14] &lt; 500 ? 500 : data[ i - 14];   //限制最小值为500(Limit the minimum value to 500)</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    //timer_sampling = millis() + 10;</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>Next, initialize glove through judgement condition function &quot;<strong>if</strong>&quot;.</p>`,2),a("p",{"lineno-start":"108"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> if (turn_on &amp;&amp; timer_init &lt; millis())</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    switch (init_step)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      case 0:</span></span>
<span class="line"><span>        digitalWrite(2, LOW);</span></span>
<span class="line"><span>        digitalWrite(3, LOW);</span></span>
<span class="line"><span>        digitalWrite(4, LOW);</span></span>
<span class="line"><span>        digitalWrite(5, LOW);</span></span>
<span class="line"><span>        digitalWrite(6, LOW);</span></span>
<span class="line"><span>        timer_init = millis() + 20;</span></span>
<span class="line"><span>        init_step++;</span></span>
<span class="line"><span>        break;</span></span>
<span class="line"><span>      case 1:</span></span>
<span class="line"><span>        digitalWrite(2, HIGH);</span></span>
<span class="line"><span>        digitalWrite(3, HIGH);</span></span>
<span class="line"><span>        digitalWrite(4, HIGH);</span></span>
<span class="line"><span>        digitalWrite(5, HIGH);</span></span>
<span class="line"><span>        digitalWrite(6, HIGH);</span></span>
<span class="line"><span>        timer_init = millis() + 200;</span></span>
<span class="line"><span>        init_step++;</span></span>
<span class="line"><span>        break;</span></span></code></pre></div><p>Since the wireless glove can control the pan-tilt rotation through rotating the wrist, it is necessary to obtain the MPU6050 data of wireless glove and update it in time.</p><p>Declare the static variable <code>timer_u</code> firstly, which is used for storing the time since the last function call. Then use judgement statement &quot;<strong>if</strong>&quot; to check if enough time has passed. If it is, execute the code within the judgement statement. Use the statement <code>accelgyro.getMotion6</code> to get raw acceleration and angular velocity data from the MPU6050sensor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void update_mpu6050()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  static uint32_t timer_u;</span></span>
<span class="line"><span>  if (timer_u &lt; millis())</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    // put your main code here, to run repeatedly:</span></span>
<span class="line"><span>    timer_u = millis() + 20;</span></span>
<span class="line"><span>    accelgyro.getMotion6(&amp;ax, &amp;ay, &amp;az, &amp;gx, &amp;gy, &amp;gz);</span></span></code></pre></div><p>As follows, three filtering formulas (such as the <code>ax0 = ((float)(ax)) * 0.3 + ax0 * 0.7)</code> filter the raw data to reduce noise.</p><p>Acceleration data is converted to a multiple of relative gravity acceleration, which is accomplished by subtracting an offset (ax_offset, ay_offset, etc.) and dividing by the constant light 8192.0.</p>`,6),a("p",{"lineno-start":"233"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    ax0 = ((float)(ax)) * 0.3 + ax0 * 0.7;  //对读取到的值进行滤波(Filter the read values)</span></span>
<span class="line"><span>    ay0 = ((float)(ay)) * 0.3 + ay0 * 0.7;</span></span>
<span class="line"><span>    az0 = ((float)(az)) * 0.3 + az0 * 0.7;</span></span>
<span class="line"><span>    ax1 = (ax0 - ax_offset) /  8192.0;  // 校正，并转为重力加速度的倍数(Correct and convert to multiples of gravity acceleration)</span></span>
<span class="line"><span>    ay1 = (ay0 - ay_offset) /  8192.0;</span></span>
<span class="line"><span>    az1 = (az0 - az_offset) /  8192.0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    gx0 = ((float)(gx)) * 0.3 + gx0 * 0.7;  //对读取到的角速度的值进行滤波(Filter the read angular velocity values)</span></span>
<span class="line"><span>    gy0 = ((float)(gy)) * 0.3 + gy0 * 0.7;</span></span>
<span class="line"><span>    gz0 = ((float)(gz)) * 0.3 + gz0 * 0.7;</span></span>
<span class="line"><span>    gx1 = (gx0 - gx_offset);  //校正角速度(Correct the angular velocity)</span></span>
<span class="line"><span>    gy1 = (gy0 - gy_offset);</span></span>
<span class="line"><span>    gz1 = (gz0 - gz_offset);</span></span></code></pre></div><p>Use the <code>atan2</code> function and calibrated acceleration data to calculate the inclination of the X and Y axis. Inclination is expressed in radians and then converted to degrees. In addition, use the complementary filter to smooth the inclination readings, which combine the data of gyroscope and accelerometer to obtain more accurate inclination readings.</p>`,2),a("p",{"lineno-start":"248"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    //互补计算x轴倾角(Complementary calculation of X-axis inclination angle)</span></span>
<span class="line"><span>    radianX = atan2(ay1, az1);</span></span>
<span class="line"><span>    radianX = radianX * 180.0 / 3.1415926;</span></span>
<span class="line"><span>    float radian_temp = (float)(gx1) / 16.4 * 0.02;</span></span>
<span class="line"><span>    radianX_last = 0.8 * (radianX_last + radian_temp) + (-radianX) * 0.2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //互补计算y轴倾角(Complementary calculation of Y-axis inclination angle)</span></span>
<span class="line"><span>    radianY = atan2(ax1, az1);</span></span>
<span class="line"><span>    radianY = radianY * 180.0 / 3.1415926;</span></span>
<span class="line"><span>    radian_temp = (float)(gy1) / 16.4 * 0.01;</span></span>
<span class="line"><span>    radianY_last = 0.8 * (radianY_last + radian_temp) + (-radianY) * 0.2;</span></span></code></pre></div><p>(5) Control Robot Hand</p><p>First, define a static floating variable <code>RadianY_Las</code> and initialize to 0. Then loop through the <code>for</code>function to assign value to each finger servo. The <code>ServoPwmSet</code> is a defined array used for storing the PWM value of the servo. Through mapping the &quot;<strong>float_map</strong>&quot; function, the PWM value of servo map the original PWM value to a new range within 1100-1950.</p>`,3),a("p",{"lineno-start":"388"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//run1, 控制手掌。(run1 controls the hand)</span></span>
<span class="line"><span>void run1(int mode)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  static float RadianY_Las = 0;</span></span>
<span class="line"><span>  // 为每个手指的舵机赋值(Assign values to each finger&#39;s servo)</span></span>
<span class="line"><span>  for (int i = 0; i &lt; 5; i++)</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    ServoPwmSet[i] = data[i]; </span></span>
<span class="line"><span>    ServoPwmSet[i] = float_map(ServoPwmSet[i], 500, 2500, 1100, 1950);</span></span>
<span class="line"><span>  }</span></span></code></pre></div><p>Based on the <code>mode</code> parameter provided, the function determines whether it is left or right hand in motion. If &quot;<strong>mode</strong>&quot; is 4, it signifies movement of the left hand; otherwise, it is the right hand in motion.</p>`,2),a("p",{"lineno-start":"398"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  int pos = 0;</span></span>
<span class="line"><span>  if(mode == 4) //当为模式4时，为左手掌(When it is mode 4, control the left hand)</span></span>
<span class="line"><span>    pos = ServoPwmSet[4];</span></span>
<span class="line"><span>  else //为模式1，右手掌(When it is mode 1, control the right hand)</span></span>
<span class="line"><span>    pos = 2750 - ServoPwmSet[4];</span></span></code></pre></div><p>If the Y-axis rotation angle is between -90 to 90 degrees, and the differences between the last Y-axis is greater than 1 degree, then: calculate the position of the pan-tilt servo based on the current Y-axis rotation angle. Use the <code>lsc.moveServos</code> function to control the position of finger servo.</p><p>If no Y-axis rotation (that is, the rotation angle of the Y-axis is not between -90 to 90 degrees), send the servo position of five fingers to the <code>lsc.moveServos</code> function.</p>`,3),a("p",{"lineno-start":"403"},null,-1),n(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  // 若有Y轴的旋转，则添加云台舵机的位置(If there is Y-axis rotation, add the position of the pan-tilt servo)</span></span>
<span class="line"><span>  if (radianY_last &lt; 90 &amp;&amp; radianY_last &gt; -90)</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>    if ( abs(radianY_last - RadianY_Las) &gt; 1)  {</span></span>
<span class="line"><span>      uint16_t se = 1500 + radianY_last*10;</span></span>
<span class="line"><span>      lsc.moveServos(6, 30, 1, 3050 - ServoPwmSet[0], 2, ServoPwmSet[1], 3, ServoPwmSet[2], 4, ServoPwmSet[3], 5, pos , 6 , se);//控制每个手指(control every finger)</span></span>
<span class="line"><span>      return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // 若无Y轴选择，则只发五个手指的舵机位置(If there is no Y-axis rotation, only send the servo positions of the five fingers)</span></span>
<span class="line"><span>  lsc.moveServos(5, 30, 1, 3050 - ServoPwmSet[0], 2, ServoPwmSet[1], 3, ServoPwmSet[2], 4, ServoPwmSet[3], 5, pos);//控制每个手指(control every finger)</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,1)])])}const J=p(X,[["render",W]]);export{Q as __pageData,J as default};
